/** High season: from December 15 to the end of February, the whole of July, and Easter week. */
static boolean isHighSeason(LocalDate date) {
    Month month = date.getMonth();
    if (month == Month.JANUARY
            || month == Month.FEBRUARY
            || month == Month.JULY
            || (month == Month.DECEMBER && date.getDayOfMonth() >= 15)) {
        return true;
    }
    if (month == Month.MARCH || month == Month.APRIL) {
        return isEasterSeason(date);
    }
    return false;
}

private static boolean isEasterSeason(LocalDate date) {
    int year = date.getYear();
    int month = date.getMonthValue();
    int day = date.getDayOfMonth();

    if (year == 2027) {
        return (month == 3 && day >= 21) || (month == 4 && day <= 28);
    } else if (year == 2028) {
        return (month == 4 && day >= 9 && day <= 16);
    }
    return false;
}

static BigDecimal cents(BigDecimal value) {
    return value.setScale(2, RoundingMode.HALF_EVEN);

